            "text": "As needed for period pain"
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-2",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-2",
        "status": "unknown",
        "medicationCodeableConcept": {
          "text": "Topical lignocaine gel (previously used; concentration not specified for past use)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "Used only a few times; not currently using."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Lignocaine 2% gel"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "Apply a small amount to the vestibule once nightly.",
            "route": {
              "text": "Topical"
            },
            "timing": {
              "repeat": {
                "frequency": 1,
                "period": 1,
                "periodUnit": "d"
              }
            }
          },
          {
            "text": "Apply a small amount to the vestibule up to 30 minutes before potential triggers. It may sting initially; wash off if significant irritation occurs. If used before intercourse, use a condom to avoid partner numbness.",
            "route": {
              "text": "Topical"
            },
            "asNeededBoolean": true
          }
        ]
      }
    }
  ]
}

